p,video/mp4,video/webm"><small>الصور حتى 4MB، الفيديو حتى 25MB.</small></label></div><?php if(!empty($banner['image'])): ?><div class="v143-media-preview"><?php if(($banner['media_type']??'image')==='video'): ?><video src="<?= e(url($banner['image'])) ?>" controls muted></video><?php else: ?><img src="<?= e(url($banner['image'])) ?>" alt="وسائط البانر الحالية"><?php endif; ?><label class="v143-switch compact"><span><b>إزالة الوسائط الحالية</b></span><input type="checkbox" name="remove_banner_media"></label></div><?php endif; ?><div class="v143-platform-link"><b>رابط المنصة</b><span><?= e($banner['platform_url']?:config('base_url','')) ?></span><small>يمكن تعديله من المظهر أو الإعدادات.</small></div><div class="v143-form-actions"><button class="btn btn-primary">حفظ البانر</button></div></form><?php if(!empty($banner['text'])||!empty($banner['image'])): ?><form method="post" action="<?= e(url('admin/banner/delete')) ?>" onsubmit="return confirm('إزالة البانر من الموقع؟')"><?= csrf_field() ?><button class="btn btn-danger-soft">إزالة البانر بالكامل</button></form><?php endif; ?></section>
<div class="v143-admin-grid top-gap"><section class="v143-panel"><div class="v143-panel-head"><div><h2>تجربة إعلانية جديدة</h2><p>اختبار A/B على مواضع آمنة فقط.</p></div></div><form class="v143-form" method="post" action="<?= e(url('admin/ad/save')) ?>"><?= csrf_field() ?><label>اسم التجربة<input name="name" required></label><label>الموضع الآمن<select name="placement"><option value="home_mid">منتصف الرئيسية</option><option value="procedures_mid">منتصف دليل الإجراءات</option><option value="article_mid">منتصف/نهاية المقال</option><option value="calculators_mid">بعد قائمة الحاسبات</option><option value="updates_mid">بعد قائمة التحديثات</option></select></label><label>رابط المنصة<input value="<?= e($banner['platform_url']?:config('base_url','')) ?>" readonly></label><label>Variant A<textarea name="variant_a" rows="5" placeholder="{{adsense}} أو {{monetag}} أو كود الاختبار"></textarea></label><label>Variant B<textarea name="variant_b" rows="5" placeholder="اتركه فارغًا لاستخدام نفس إعلان A، أو ضع شبكة أخرى للمقارنة"></textarea></label><div class="v143-form-grid"><label>حصة A %<input type="number" min="1" max="99" name="traffic_split" value="50"></label><label>الحالة<select name="status"><option value="draft">مسودة</option><option value="running">تشغيل</option><option value="paused">إيقاف مؤقت</option></select></label></div><button class="btn btn-primary">إنشاء التجربة</button></form><div class="notice-card warning"><b>حماية إلزامية</b><p>لا توجد خيارات لمواضع داخل بطاقة الخطوة أو بجوار زر التنفيذ الرسمي.</p></div></section><section class="v143-panel"><div class="v143-panel-head"><h2>التجارب</h2></div><div class="v143-experiment-list"><?php foreach($experiments as $x): $m=\Khatauat\Core\Database::fetch('SELECT SUM(event_type="impression") imp,SUM(event_type="click") clk FROM ad_experiment_events WHERE experiment_id=?',[(int)$x['id']]);$imp=(int)($m['imp']??0);$clk=(int)($m['clk']??0);$ctr=$imp>0?round(($clk/$imp)*100,2):0; ?><article class="v143-experiment"><div class="v143-experiment-top"><div><span class="badge <?= $x['status']==='running'?'badge-success':'badge-warn' ?>"><?= e($x['status']) ?></span><h3><?= e($x['name']) ?></h3><p><?= e(([
"home_mid"=>"منتصف الرئيسية",
"procedures_mid"=>"دليل الإجراءات",
"article_mid"=>"المقالات",
"calculators_mid"=>"قائمة الحاسبات",
"updates_mid"=>"التحديثات"
][(string)$x["placement"]] ?? (string)$x["placement"])) ?> • A <?= (int)$x['traffic_split'] ?>% / B <?= 100-(int)$x['traffic_split'] ?>%</p></div><div class="v143-experiment-metrics"><span><b><?= $imp ?></b> عرض موضع</span><span><b><?= $clk ?></b> نقر</span><span><b><?= e((string)$ctr) ?>%</b> معدل التفاعل</span></div></div><form class="v143-inline-form" method="post" action="<?= e(url('admin/ad/status')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$x['id'] ?>"><select name="status"><option value="running" <?= $x['status']==='running'?'selected':'' ?>>تشغيل</option><option value="paused" <?= $x['status']==='paused'?'selected':'' ?>>إيقاف مؤقت</option><option value="draft" <?= $x['status']==='draft'?'selected':'' ?>>مسودة</option><option value="ended" <?= $x['status']==='ended'?'selected':'' ?>>إنهاء</option></select><button class="btn btn-soft btn-sm">تحديث</button></form></article><?php endforeach; ?><?php if(!$experiments): ?><div class="empty-state">لا توجد تجارب بعد.</div><?php endif; ?></div></section></div></div></div></section>